const ws = wb.getWorksheet('start');
const cleared = [], filled = [];
let cur = null;
for (let r = 3; r <= 36; r++) {
  const e = wb.getRange(`start!E${r}`).getValues()[0][0];
  const f = wb.getRange(`start!F${r}`).getValues()[0][0];
  const a = wb.getRange(`start!A${r}`).getValues()[0][0];
  if (e === 'column5') { cur = null; continue; } // repeated header row
  if (e === null && f !== null) { wb.getRange(`start!F${r}`).setValue(null); cleared.push(r); cur = null; continue; }
  if (a !== null) { cur = a; continue; }
  if (cur !== null) { wb.getRange(`start!A${r}`).setValue("'" + cur); filled.push(r); }
}
log('cleared F', cleared.join(','));
log('filled A', filled.join(','));
const out = wb.getRange('start!A3:F36');
out.getValues().map((x,i)=>(i+3)+': '+JSON.stringify(x)).join('\n')

