wb.getRange('start!F16').clear('values'); wb.getRange('start!F30').clear('values');
const v = wb.getRange('start!A1:F40').getValues();
const bad = [];
for (let i=2;i<36;i++){ const r=i+1, [a,,,,e,f]=v[i];
  if (r===29) continue;
  if ((e===null) !== (f===null)) bad.push('EF'+r);
  if ((e===null) !== (a===null)) bad.push('AE'+r);
}
log('violations', bad.join(',')||'none');
log('blank F', v.map((x,i)=>x[5]===null&&i>=2&&i<36?i+1:0).filter(Boolean).join(','));
log('A types', [...new Set(v.slice(2,36).map(x=>typeof x[0]))].join(','));
log('row 1-2', JSON.stringify(v.slice(0,2)));
log('A29:F29', JSON.stringify(v[28]));
v.slice(2,36).map((x,i)=>(i+3)+': '+JSON.stringify(x)).join('\n')

